        protected string GetContentPreview(object objValue)
        {
            if (objValue == null || objValue == DBNull.Value)
                return string.Empty;

            string strText = Convert.ToString(objValue);
            if (string.IsNullOrEmpty(strText))
                return string.Empty;

            strText = Regex.Replace(strText, "<[^>]+>", " ");
            strText = strText.Replace("\r", " ").Replace("\n", " ").Trim();

            while (strText.Contains("  "))
                strText = strText.Replace("  ", " ");

            return strText;
        }
    }
